// WP-Lingo Daten: Wirtschaftsrecht. Die ERSTE Antwortoption ist immer die richtige.
var RECHT = [
 { title:"BGB: Allgemeiner Teil & Vertrag", icon:"📗", qs:[
  {q:"Ein 16-Jähriger kauft ohne Wissen seiner Eltern ein Smartphone für 800 € auf Raten. Wie ist der Kaufvertrag zu beurteilen?",
   h:"Prüfe die Geschäftsfähigkeit nach Alter (§§ 104 ff. BGB). Ist das Geschäft lediglich rechtlich vorteilhaft? Greift der Taschengeldparagraf bei Ratenzahlung?",
   o:[["Schwebend unwirksam; die Eltern können genehmigen (§§ 107, 108 BGB)","Der Minderjährige ist beschränkt geschäftsfähig (§ 106 BGB). Der Vertrag ist rechtlich nachteilig (Zahlungspflicht), deshalb ist die Einwilligung der gesetzlichen Vertreter erforderlich."],
      ["Nichtig nach § 105 BGB","Nichtig sind Willenserklärungen Geschäftsunfähiger, also von Kindern unter 7 Jahren (§ 104 Nr. 1 BGB)."],
      ["Wirksam nach § 110 BGB (Taschengeldparagraf)","§ 110 BGB setzt voraus, dass die Leistung vollständig mit überlassenen Mitteln bewirkt ist. Bei Ratenzahlung ist das erst mit der letzten Rate der Fall."],
      ["Voll wirksam, aber anfechtbar","Die Minderjährigkeit ist kein Anfechtungsgrund. Die §§ 107 ff. BGB regeln die Folgen abschließend."]],
   n:"§ 108 Abs. 2 BGB: Fordert der Vertragspartner zur Genehmigung auf, gilt sie als verweigert, wenn sie nicht binnen zwei Wochen erklärt wird."},
  {q:"Kaufmann A erhält von Kaufmann B ein kaufmännisches Bestätigungsschreiben über einen telefonisch besprochenen Vertrag, das vom Gespräch leicht abweicht. A reagiert nicht. Was gilt?",
   h:"Denk an die Grundsätze zum Schweigen im Handelsverkehr. Wann schadet Schweigen ausnahmsweise?",
   o:[["Der Vertrag gilt mit dem Inhalt des Schreibens als geschlossen, wenn A nicht unverzüglich widerspricht","Gewohnheitsrecht bzw. Handelsbrauch (§ 346 HGB). Grenze: Der Absender durfte nicht mit Zustimmung rechnen, z. B. bei bewusst falscher Wiedergabe oder erheblichen Abweichungen."],
      ["Schweigen gilt immer als Ablehnung","Das ist der Grundsatz im allgemeinen Zivilrecht. Unter Kaufleuten gilt beim Bestätigungsschreiben eine Ausnahme."],
      ["Der Vertrag kommt nur zustande, wenn A schriftlich bestätigt","Gerade das Schweigen löst die Wirkung aus."],
      ["Die Grundsätze gelten genauso zwischen Privatpersonen","Sie setzen voraus, dass beide Seiten wie Kaufleute am Geschäftsverkehr teilnehmen."]],
   n:"Weiterer Fall des beredten Schweigens: § 362 HGB (Schweigen auf einen Geschäftsbesorgungsantrag)."},
  {q:"Ein Käufer erfährt am 1.3.2026, dass er beim Autokauf arglistig über einen Unfallschaden getäuscht wurde. Bis wann kann er anfechten?",
   h:"Unterscheide die Fristen für die Irrtumsanfechtung (§ 121 BGB) und die Anfechtung wegen Täuschung oder Drohung (§ 124 BGB). Wann beginnt die Frist?",
   o:[["Innerhalb eines Jahres ab Entdeckung der Täuschung, also bis zum 1.3.2027","§ 124 Abs. 1 und 2 BGB. Absolute Grenze: 10 Jahre ab Abgabe der Willenserklärung (§ 124 Abs. 3 BGB)."],
      ["Nur unverzüglich, also ohne schuldhaftes Zögern","Das gilt für die Irrtumsanfechtung nach §§ 119, 120 BGB (§ 121 BGB)."],
      ["Innerhalb von zwei Wochen","Zwei Wochen gelten für die außerordentliche Kündigung (§ 626 Abs. 2 BGB)."],
      ["Innerhalb der dreijährigen Regelverjährung","Die Anfechtung ist ein Gestaltungsrecht mit eigener Ausschlussfrist, sie verjährt nicht."]],
   n:"Rechtsfolge der Anfechtung: Nichtigkeit von Anfang an (§ 142 Abs. 1 BGB)."},
  {q:"V schließt im Namen des U einen Vertrag mit D, obwohl er keine Vollmacht hat. U verweigert die Genehmigung. Wer haftet D gegenüber?",
   h:"Ohne Vertretungsmacht ist der Vertrag zunächst schwebend unwirksam (§ 177 BGB). Prüfe dann die Haftung des Vertreters ohne Vertretungsmacht.",
   o:[["V haftet nach Wahl des D auf Erfüllung oder Schadensersatz, wenn er den Mangel der Vertretungsmacht kannte (§ 179 Abs. 1 BGB)","Kannte V den Mangel nicht, haftet er nur auf den Vertrauensschaden (§ 179 Abs. 2 BGB). Kannte D den Mangel, ist die Haftung ausgeschlossen (§ 179 Abs. 3 BGB)."],
      ["U haftet trotzdem aus dem Vertrag","Ohne Vertretungsmacht und Genehmigung wird U nicht verpflichtet. Ausnahme: Rechtsscheinvollmacht (Duldungs- oder Anscheinsvollmacht)."],
      ["Der Vertrag wird nach zwei Wochen automatisch wirksam","Schweigen auf die Aufforderung zur Genehmigung gilt nach zwei Wochen als Verweigerung (§ 177 Abs. 2 BGB)."],
      ["Niemand, D trägt das Risiko allein","§ 179 BGB schützt gerade den Vertragspartner."]],
   n:"Duldungsvollmacht: Der Vertretene kennt das Auftreten und duldet es. Anscheinsvollmacht: Er hätte es erkennen und verhindern können."},
  {q:"Ein Käufer erhält eine mangelhafte Maschine. Wer entscheidet, ob nachgebessert oder eine neue Maschine geliefert wird?",
   h:"Vergleiche Kaufrecht (§ 439 BGB) und Werkvertragsrecht (§ 635 BGB). Bei wem liegt jeweils das Wahlrecht?",
   o:[["Der Käufer (§ 439 Abs. 1 BGB)","Der Verkäufer kann die gewählte Art nur bei unverhältnismäßigen Kosten verweigern (§ 439 Abs. 4 BGB)."],
      ["Der Verkäufer","Beim Werkvertrag wählt der Unternehmer (§ 635 Abs. 1 BGB), beim Kauf nicht."],
      ["Das Gericht","Eine gerichtliche Bestimmung ist nicht vorgesehen."],
      ["Niemand: Der Käufer muss sofort zurücktreten","Vorrang hat die Nacherfüllung. Rücktritt und Minderung setzen grundsätzlich eine erfolglose Fristsetzung voraus (§§ 437, 323 BGB)."]],
   n:"Rechte des Käufers (§ 437 BGB): Nacherfüllung → Rücktritt oder Minderung → Schadensersatz bzw. Aufwendungsersatz."},
  {q:"Verbrauchsgüterkauf: Ein Mangel zeigt sich 10 Monate nach Übergabe. Was wird zugunsten des Verbrauchers vermutet?",
   h:"§ 477 BGB wurde 2022 geändert. Wie lang ist der Vermutungszeitraum heute?",
   o:[["Dass der Mangel schon bei Gefahrübergang vorlag, weil die Vermutung ein Jahr gilt (§ 477 Abs. 1 BGB)","Seit 1.1.2022 gilt ein Jahr statt sechs Monate. Der Verkäufer muss das Gegenteil beweisen."],
      ["Nichts, weil die Vermutung nur sechs Monate gilt","Sechs Monate galten bis 31.12.2021."],
      ["Dass der Verkäufer arglistig gehandelt hat","Eine Arglistvermutung gibt es nicht."],
      ["Die Vermutung gilt auch zwischen zwei Unternehmern","§ 477 BGB gilt nur beim Verbrauchsgüterkauf (§ 474 BGB)."]],
   n:"Bei Waren mit digitalen Elementen und dauerhafter Bereitstellung gilt eine längere Vermutung (§ 477 Abs. 2 BGB)."}
 ]},
 { title:"Kreditsicherheiten & Sachenrecht", icon:"🔐", qs:[
  {q:"Ein Kaufmann übernimmt im Rahmen seines Handelsgewerbes mündlich eine Bürgschaft. Was gilt?",
   h:"Vergleiche § 766 BGB und § 771 BGB mit den Sonderregeln für Kaufleute in den §§ 349, 350 HGB.",
   o:[["Die Bürgschaft ist formfrei wirksam, und die Einrede der Vorausklage steht ihm nicht zu","§ 350 HGB (keine Schriftform) und § 349 HGB (selbstschuldnerische Bürgschaft)."],
      ["Unwirksam, weil § 766 BGB die Schriftform verlangt","§ 766 BGB gilt nicht für Bürgschaften, die für den Bürgen ein Handelsgeschäft sind (§ 350 HGB)."],
      ["Wirksam nur bei notarieller Beurkundung","Eine Beurkundung ist für Bürgschaften nicht erforderlich."],
      ["Wirksam, der Bürge kann aber verlangen, dass zuerst gegen den Hauptschuldner vollstreckt wird","Die Einrede der Vorausklage (§ 771 BGB) ist bei Kaufleuten ausgeschlossen (§ 349 HGB)."]],
   n:"Die Bürgschaft ist akzessorisch: Der Bürge kann die Einreden des Hauptschuldners geltend machen (§ 768 BGB)."},
  {q:"Was bedeutet ein (einfacher) Eigentumsvorbehalt rechtlich?",
   h:"Wann geht das Eigentum über, und welche Art von Bedingung wird vereinbart (§ 158 BGB)?",
   o:[["Die Übereignung erfolgt aufschiebend bedingt durch die vollständige Kaufpreiszahlung (§§ 449, 929, 158 Abs. 1 BGB)","Der Käufer erhält sofort Besitz und ein Anwartschaftsrecht. Eigentümer wird er erst mit der letzten Zahlung."],
      ["Die Übereignung erfolgt sofort, aber auflösend bedingt","Beim Eigentumsvorbehalt ist die Bedingung aufschiebend, nicht auflösend."],
      ["Der Verkäufer erhält ein Pfandrecht","Ein Pfandrecht setzt den Besitz des Gläubigers voraus (§ 1205 BGB)."],
      ["Es handelt sich um eine Sicherungsübereignung","Bei der Sicherungsübereignung überträgt der Schuldner Eigentum an den Gläubiger, also genau umgekehrt."]],
   n:"Verlängerter EV: Vorausabtretung der Forderungen aus dem Weiterverkauf. Erweiterter EV: Eigentum erst nach Tilgung weiterer Forderungen."},
  {q:"Eine GmbH übereignet ihre Maschinen zur Sicherung eines Kredits an die Bank, will sie aber weiter nutzen. Wie erfolgt die Übereignung?",
   h:"Wer soll den unmittelbaren Besitz behalten? Welche Ersatzformen der Übergabe kennt das BGB (§§ 930, 931)?",
   o:[["Einigung und Vereinbarung eines Besitzkonstituts (§§ 929 S. 1, 930 BGB)","Die GmbH bleibt unmittelbare Besitzerin, die Bank wird mittelbare Besitzerin. Der Sicherungsvertrag ist das Besitzmittlungsverhältnis."],
      ["Durch Einigung und Übergabe der Maschinen an die Bank","Dann könnte die GmbH die Maschinen nicht mehr nutzen."],
      ["Durch Eintragung in ein Register","Ein Register für bewegliche Sachen gibt es nicht. Deshalb ist die Sicherungsübereignung für Dritte nicht erkennbar."],
      ["Sie ist nicht möglich, nur eine Verpfändung","Die Sicherungsübereignung ist von der Rechtsprechung allgemein anerkannt."]],
   n:"In der Insolvenz des Sicherungsgebers hat die Bank ein Absonderungsrecht (§ 51 Nr. 1 InsO), kein Aussonderungsrecht."},
  {q:"Ein Dieb verkauft ein gestohlenes Fahrrad an einen gutgläubigen Käufer. Wird der Käufer Eigentümer?",
   h:"Prüfe § 932 BGB und die Ausnahme in § 935 BGB. Gibt es Rückausnahmen?",
   o:[["Nein, ein gutgläubiger Erwerb abhanden gekommener Sachen ist ausgeschlossen (§ 935 Abs. 1 BGB)","Rückausnahme: Geld, Inhaberpapiere und Sachen, die öffentlich versteigert werden (§ 935 Abs. 2 BGB)."],
      ["Ja, weil er gutgläubig ist (§ 932 BGB)","§ 932 BGB wird durch § 935 BGB eingeschränkt."],
      ["Ja, wenn er einen marktüblichen Preis gezahlt hat","Der Preis spielt nur für die Gutgläubigkeit eine Rolle, nicht für § 935 BGB."],
      ["Ja, nach zwei Jahren automatisch","Die Ersitzung setzt 10 Jahre gutgläubigen Eigenbesitz voraus (§ 937 BGB)."]],
   n:"Abhandenkommen = unfreiwilliger Verlust des unmittelbaren Besitzes. Eine Unterschlagung durch einen Entleiher ist kein Abhandenkommen."},
  {q:"Worin unterscheidet sich die Grundschuld von der Hypothek?",
   h:"Hängt das Sicherungsrecht vom Bestand einer Forderung ab (Akzessorietät)?",
   o:[["Die Grundschuld ist nicht akzessorisch, die Hypothek schon","Die Verknüpfung mit der Forderung erfolgt bei der Grundschuld über den Sicherungsvertrag (Sicherungsgrundschuld)."],
      ["Die Grundschuld ist akzessorisch, die Hypothek nicht","Genau umgekehrt (§ 1113 BGB vs. § 1191 BGB)."],
      ["Nur die Hypothek wird ins Grundbuch eingetragen","Beide sind Grundpfandrechte und werden eingetragen."],
      ["Es gibt keinen Unterschied","Die fehlende Akzessorietät macht die Grundschuld in der Praxis flexibler und verbreiteter."]],
   n:"Bei der Sicherungsgrundschuld kann der Eigentümer Einreden aus dem Sicherungsvertrag auch einem Erwerber entgegenhalten (§ 1192 Abs. 1a BGB)."},
  {q:"Eine GmbH zahlt eine Rechnung eines anderen Unternehmens verspätet. Wie hoch ist der gesetzliche Verzugszins?",
   h:"§ 288 BGB unterscheidet, ob ein Verbraucher beteiligt ist. Achte auch auf die Pauschale.",
   o:[["9 Prozentpunkte über dem Basiszinssatz, zusätzlich 40 € Pauschale","§ 288 Abs. 2 und Abs. 5 BGB für Entgeltforderungen, wenn kein Verbraucher beteiligt ist."],
      ["5 Prozentpunkte über dem Basiszinssatz","Das gilt, wenn ein Verbraucher beteiligt ist (§ 288 Abs. 1 BGB)."],
      ["8 Prozentpunkte über dem Basiszinssatz","Das war die Rechtslage bis Juli 2014."],
      ["Fest 4 % pro Jahr","4 % ist der allgemeine gesetzliche Zinssatz (§ 246 BGB). 5 % gilt bei beiderseitigen Handelsgeschäften (§ 352 HGB)."]],
   n:"Verzug ohne Mahnung bei Entgeltforderungen spätestens 30 Tage nach Fälligkeit und Rechnungszugang (§ 286 Abs. 3 BGB)."}
 ]},
 { title:"Handelsrecht", icon:"📕", qs:[
  {q:"Eine GmbH betreibt nur eine kleine Hausverwaltung. Ist sie Kaufmann im Sinne des HGB?",
   h:"Unterscheide Istkaufmann (§ 1 HGB), Kannkaufmann (§ 2 HGB) und Formkaufmann (§ 6 HGB).",
   o:[["Ja, als Formkaufmann unabhängig von Art und Umfang des Geschäfts (§ 6 HGB, § 13 Abs. 3 GmbHG)","Die GmbH gilt kraft Rechtsform als Handelsgesellschaft und damit als Kaufmann."],
      ["Nein, weil kein kaufmännisch eingerichteter Geschäftsbetrieb erforderlich ist","Das ist für den Istkaufmann (§ 1 Abs. 2 HGB) relevant, nicht für die GmbH."],
      ["Nur, wenn sie sich freiwillig eintragen lässt (§ 2 HGB)","Die GmbH entsteht erst mit Eintragung und ist dann ohnehin Formkaufmann."],
      ["Nein, Hausverwaltung ist kein Gewerbe","Auch ohne Gewerbe ist die GmbH Formkaufmann."]],
   n:"Folge: Es gelten u. a. die §§ 343 ff. HGB (Handelsgeschäfte), z. B. die Rügeobliegenheit nach § 377 HGB."},
  {q:"Ein Prokurist darf intern nur Geschäfte bis 50.000 € abschließen. Er kauft trotzdem für 80.000 € ein. Ist der Vertrag wirksam?",
   h:"Schau in § 50 HGB. Unterscheide Innen- und Außenverhältnis.",
   o:[["Ja, eine Beschränkung des Umfangs der Prokura ist Dritten gegenüber unwirksam (§ 50 Abs. 1 HGB)","Intern kann sich der Prokurist schadensersatzpflichtig machen. Ausnahme: offensichtlicher Missbrauch der Vertretungsmacht oder Zusammenwirken mit dem Dritten."],
      ["Nein, er hat seine Vertretungsmacht überschritten","Der Umfang der Prokura ist gesetzlich festgelegt (§ 49 HGB) und nach außen nicht beschränkbar."],
      ["Nur bis zu 50.000 €","Eine Teilwirksamkeit gibt es nicht."],
      ["Nur, wenn die Beschränkung nicht im Handelsregister steht","Die Beschränkung ist gar nicht eintragungsfähig."]],
   n:"Zulässig sind nur die Gesamtprokura (§ 48 Abs. 2 HGB) und die Filialprokura (§ 50 Abs. 3 HGB)."},
  {q:"Ein Unternehmen widerruft die Prokura von P, lässt den Widerruf aber nicht im Handelsregister eintragen. P schließt danach einen Vertrag mit dem gutgläubigen D. Was gilt?",
   h:"Ist das Erlöschen der Prokura eintragungspflichtig (§ 53 Abs. 2 HGB)? Was regelt die negative Publizität (§ 15 Abs. 1 HGB)?",
   o:[["Das Unternehmen kann D den Widerruf nicht entgegenhalten und ist gebunden (§ 15 Abs. 1 HGB)","Eintragungspflichtige Tatsachen wirken gegenüber gutgläubigen Dritten erst nach Eintragung und Bekanntmachung."],
      ["Der Vertrag ist unwirksam, weil P keine Prokura mehr hatte","Das wäre die materielle Rechtslage. § 15 Abs. 1 HGB schützt aber das Vertrauen des D."],
      ["P haftet allein nach § 179 BGB","D kann sich auf § 15 Abs. 1 HGB berufen und das Unternehmen in Anspruch nehmen."],
      ["Der Widerruf wirkt, weil die Eintragung nur deklaratorisch wäre","Auch deklaratorische Eintragungen sind für § 15 Abs. 1 HGB maßgeblich."]],
   n:"§ 15 Abs. 3 HGB (positive Publizität): Auf eine unrichtig bekanntgemachte Tatsache kann sich ein gutgläubiger Dritter berufen."},
  {q:"K erwirbt das Handelsgeschäft des V und führt es unter der bisherigen Firma fort. Ein Haftungsausschluss wurde nicht eingetragen. Haftet K für die alten Geschäftsschulden des V?",
   h:"§ 25 HGB knüpft an die Firmenfortführung an. Wann ist ein Haftungsausschluss wirksam?",
   o:[["Ja, für alle im Betrieb begründeten Verbindlichkeiten (§ 25 Abs. 1 HGB)","Ein Ausschluss wirkt nur bei Eintragung und Bekanntmachung im Handelsregister oder Mitteilung an den Gläubiger (§ 25 Abs. 2 HGB)."],
      ["Nein, Schulden gehen nur mit Zustimmung der Gläubiger über (§ 415 BGB)","§ 25 HGB ordnet eine gesetzliche Haftung an, ohne Zustimmung der Gläubiger."],
      ["Nur bis zur Höhe des Kaufpreises","Die Haftung nach § 25 HGB ist unbeschränkt."],
      ["Nein, der frühere Inhaber haftet allein","V haftet weiter, zeitlich begrenzt auf 5 Jahre (§ 26 HGB). Daneben haftet K."]],
   n:"Ohne Firmenfortführung haftet der Erwerber nur bei besonderem Verpflichtungsgrund, z. B. Bekanntmachung der Übernahme (§ 25 Abs. 3 HGB)."},
  {q:"Ein Großhändler kauft Ware bei einem Hersteller (beide Kaufleute). Er entdeckt einen offensichtlichen Mangel, rügt aber erst nach drei Wochen. Was folgt?",
   h:"Prüfe § 377 HGB: beiderseitiges Handelsgeschäft, Untersuchung und unverzügliche Rüge.",
   o:[["Die Ware gilt als genehmigt; der Käufer verliert seine Mängelrechte (§ 377 Abs. 2 HGB)","Offensichtliche Mängel sind unverzüglich nach Ablieferung und Untersuchung zu rügen. Drei Wochen sind regelmäßig zu spät."],
      ["Er behält alle Rechte, weil die Verjährung zwei Jahre beträgt","Die Rügeobliegenheit geht der Verjährung vor."],
      ["Er kann nur noch mindern","Bei der Genehmigungsfiktion entfallen alle Mängelrechte."],
      ["§ 377 HGB gilt nur gegenüber Verbrauchern","§ 377 HGB setzt gerade ein beiderseitiges Handelsgeschäft voraus."]],
   n:"Ausnahme: Der Verkäufer hat den Mangel arglistig verschwiegen (§ 377 Abs. 5 HGB)."},
  {q:"Wie hoch ist der Ausgleichsanspruch des Handelsvertreters nach Vertragsende höchstens?",
   h:"§ 89b Abs. 2 HGB enthält eine Obergrenze, die an die Provisionen der letzten Jahre anknüpft.",
   o:[["Eine Jahresprovision, berechnet aus dem Durchschnitt der letzten fünf Jahre","§ 89b Abs. 2 HGB. Bei kürzerer Vertragsdauer zählt der Durchschnitt während der Vertragsdauer."],
      ["Zwei Jahresprovisionen","Diese Grenze gibt es im HGB nicht."],
      ["Drei Monatsprovisionen","Das ist keine gesetzliche Grenze."],
      ["Es gibt keinen Ausgleichsanspruch","Der Anspruch ist zwingend und kann im Voraus nicht ausgeschlossen werden (§ 89b Abs. 4 HGB)."]],
   n:"Der Anspruch muss innerhalb eines Jahres nach Vertragsende geltend gemacht werden (§ 89b Abs. 4 S. 2 HGB)."}
 ]},
 { title:"Personengesellschaften (MoPeG)", icon:"👥", qs:[
  {q:"Drei Freiberufler gründen 2026 eine GbR, die nach außen auftreten soll. Was gilt seit dem MoPeG?",
   h:"§ 705 Abs. 2 BGB n. F. unterscheidet die rechtsfähige und die nicht rechtsfähige GbR.",
   o:[["Die GbR ist selbst rechtsfähig, wenn sie nach dem gemeinsamen Willen am Rechtsverkehr teilnehmen soll","§ 705 Abs. 2 BGB (seit 1.1.2024). Eine Eintragung im Gesellschaftsregister ist möglich (§ 707 BGB), aber keine Voraussetzung."],
      ["Die GbR ist nur rechtsfähig, wenn sie im Handelsregister eingetragen ist","Die GbR wird nicht ins Handelsregister, sondern freiwillig ins Gesellschaftsregister eingetragen."],
      ["Rechtsfähig sind nur die Gesellschafter, nicht die GbR","Das entspricht der überholten Sichtweise vor der BGH-Rechtsprechung von 2001."],
      ["Die GbR ist stets eine juristische Person","Die rechtsfähige GbR ist rechtsfähig, aber keine juristische Person."]],
   n:"Faktisch nötig ist die Eintragung z. B. für Grundstücksgeschäfte (Voreintragungsgrundsatz, § 47 Abs. 2 GBO)."},
  {q:"Wie haften die Gesellschafter einer rechtsfähigen GbR für Verbindlichkeiten der Gesellschaft?",
   h:"Seit dem MoPeG ist die Haftung ausdrücklich im BGB geregelt (§ 721 BGB), parallel zur OHG.",
   o:[["Persönlich, unbeschränkt und als Gesamtschuldner (§ 721 BGB)","Eine abweichende Vereinbarung wirkt Dritten gegenüber nicht (§ 721 S. 2 BGB)."],
      ["Nur mit dem Gesellschaftsvermögen","Das gilt bei Kapitalgesellschaften, nicht bei der GbR."],
      ["Nur anteilig nach ihrer Beteiligung","Jeder Gesellschafter haftet für die ganze Schuld."],
      ["Nur, wenn die GbR eingetragen ist","Die Haftung hängt nicht von der Eintragung ab."]],
   n:"OHG: § 126 HGB n. F. (früher § 128 HGB)."},
  {q:"N tritt 2026 als neuer Gesellschafter in eine bestehende OHG ein. Haftet er für Verbindlichkeiten, die vor seinem Eintritt entstanden sind?",
   h:"Seit dem MoPeG regelt § 127 HGB die Haftung des eintretenden Gesellschafters (früher § 130 HGB).",
   o:[["Ja, er haftet wie die anderen Gesellschafter auch für die Altverbindlichkeiten (§ 127 HGB)","Eine entgegenstehende Vereinbarung ist Dritten gegenüber unwirksam."],
      ["Nein, nur für Neuverbindlichkeiten","Gerade die Altverbindlichkeiten sind erfasst."],
      ["Nur bis zur Höhe seiner Einlage","Das gilt für Kommanditisten (§ 171 HGB), nicht für OHG-Gesellschafter."],
      ["Nur, wenn er die Schulden kannte","Auf Kenntnis kommt es nicht an."]],
   n:"Auch beim Eintritt in eine GbR haftet der Neue für Altverbindlichkeiten (§ 721a BGB)."},
  {q:"Gesellschafter A scheidet aus einer OHG aus. Wie lange haftet er noch für die bis dahin begründeten Verbindlichkeiten?",
   h:"Die Nachhaftung ist zeitlich begrenzt (§ 137 HGB n. F., früher § 160 HGB). Ab wann läuft die Frist?",
   o:[["Für Verbindlichkeiten, die innerhalb von 5 Jahren nach dem Ausscheiden fällig und gerichtlich geltend gemacht werden","Die Frist beginnt grundsätzlich mit Eintragung des Ausscheidens im Handelsregister, bei früherer Kenntnis des Gläubigers ab Kenntnis."],
      ["Gar nicht mehr ab dem Ausscheiden","Für Altverbindlichkeiten besteht eine Nachhaftung."],
      ["Unbegrenzt","Die Haftung ist auf 5 Jahre begrenzt (Enthaftung)."],
      ["3 Jahre","3 Jahre ist die regelmäßige Verjährungsfrist (§ 195 BGB), nicht die Nachhaftungsfrist."]],
   n:"Für die GbR gilt entsprechend § 728b BGB."},
  {q:"Welche Rechte haben Kommanditisten bei der Geschäftsführung einer KG?",
   h:"Vergleiche § 164 HGB (Geschäftsführung) mit § 170 HGB (Vertretung).",
   o:[["Sie sind von der Geschäftsführung ausgeschlossen, können aber außergewöhnlichen Geschäften widersprechen (§ 164 HGB)","Zur Vertretung sind Kommanditisten nicht ermächtigt (§ 170 HGB). Möglich bleibt die Erteilung einer Prokura."],
      ["Sie führen die Geschäfte gemeinsam mit den Komplementären","Geschäftsführung und Vertretung liegen bei den Komplementären."],
      ["Sie haben keinerlei Mitwirkungs- oder Kontrollrechte","Sie haben z. B. Informationsrechte (§ 166 HGB) und das Widerspruchsrecht nach § 164 HGB."],
      ["Sie vertreten die KG nach außen","Nach § 170 HGB sind Kommanditisten nicht zur Vertretung befugt."]],
   n:"Die Regeln zur Geschäftsführung sind abdingbar, die zur Vertretung nicht."},
  {q:"In einer typischen GmbH & Co. KG ist die GmbH einzige Komplementärin. Wer haftet den Gläubigern der KG unbeschränkt?",
   h:"Komplementäre haften unbeschränkt, Kommanditisten beschränkt. Wer ist hier Komplementär, und womit haftet er?",
   o:[["Die Komplementär-GmbH mit ihrem gesamten Vermögen","Weil die GmbH selbst nur mit ihrem Vermögen haftet, haftet im Ergebnis keine natürliche Person unbeschränkt."],
      ["Die Geschäftsführer der GmbH persönlich","Geschäftsführer haften nicht für Gesellschaftsschulden. Ausnahmen sind z. B. § 15b InsO oder § 43 GmbHG im Innenverhältnis."],
      ["Die Kommanditisten","Sie haften nur bis zur Höhe ihrer Haftsumme und nicht mehr, soweit die Einlage geleistet ist (§ 171 HGB)."],
      ["Niemand","Die Komplementär-GmbH haftet unbeschränkt."]],
   n:"Die Firma muss die Haftungsbeschränkung erkennen lassen (§ 19 Abs. 2 HGB), z. B. „GmbH & Co. KG“."}
 ]},
 { title:"GmbH-Recht", icon:"🏢", qs:[
  {q:"Bargründung einer GmbH mit 25.000 € Stammkapital und zwei Gesellschaftern zu je 12.500 €. Wie viel muss vor der Anmeldung insgesamt mindestens eingezahlt sein?",
   h:"§ 7 Abs. 2 GmbHG enthält zwei Untergrenzen: eine je Geschäftsanteil und eine insgesamt.",
   o:[["12.500 €","Je Anteil mindestens ein Viertel (3.125 €), insgesamt aber mindestens die Hälfte des Mindeststammkapitals (§ 7 Abs. 2 GmbHG)."],
      ["6.250 €","Das ist nur ein Viertel je Anteil. Die Gesamtgrenze von 12.500 € fehlt."],
      ["25.000 €","Volleinzahlung ist nur bei der UG (§ 5a Abs. 2 GmbHG) und bei Sacheinlagen vorgeschrieben."],
      ["0 €","Ohne Mindesteinzahlung darf nicht angemeldet werden."]],
   n:"Mindeststammkapital 25.000 € (§ 5 Abs. 1 GmbHG); AG: Grundkapital 50.000 € (§ 7 AktG)."},
  {q:"Wie wird ein GmbH-Geschäftsanteil wirksam abgetreten?",
   h:"§ 15 GmbHG regelt die Form. Ist die neue Gesellschafterliste Wirksamkeitsvoraussetzung?",
   o:[["Durch notariell beurkundeten Vertrag (§ 15 Abs. 3 GmbHG)","Die geänderte Gesellschafterliste (§ 40 GmbHG) ist für die Legitimation gegenüber der Gesellschaft wichtig (§ 16 Abs. 1 GmbHG), aber keine Wirksamkeitsvoraussetzung der Abtretung."],
      ["Durch einfachen schriftlichen Vertrag","Die Schriftform reicht nicht."],
      ["Formfrei","Anders als Aktien sind GmbH-Anteile nicht formfrei übertragbar."],
      ["Erst mit Eintragung ins Handelsregister","Der Gesellschafterwechsel wird nicht eingetragen. Im Register wird nur die neue Liste aufgenommen."]],
   n:"Ein gutgläubiger Erwerb von Geschäftsanteilen ist über die Gesellschafterliste möglich (§ 16 Abs. 3 GmbHG)."},
  {q:"Die GmbH (Stammkapital 25.000 €, Reinvermögen 20.000 €) zahlt einem Gesellschafter ohne Gegenleistung 10.000 €. Was gilt?",
   h:"§ 30 Abs. 1 GmbHG: Das zur Erhaltung des Stammkapitals erforderliche Vermögen darf nicht ausgezahlt werden. Liegt eine Unterbilanz vor?",
   o:[["Verbotene Auszahlung; der Gesellschafter muss die 10.000 € erstatten (§ 31 Abs. 1 GmbHG)","Schon vor der Zahlung bestand eine Unterbilanz, sie wird vertieft. Der Geschäftsführer haftet zusätzlich nach § 43 Abs. 3 GmbHG."],
      ["Zulässig, solange die Gesellschaft zahlungsfähig ist","Maßgeblich ist die bilanzielle Kapitalbindung, nicht die Liquidität."],
      ["Zulässig bis zur Höhe von 50 % des Stammkapitals","Eine solche Grenze gibt es nicht."],
      ["Die Zahlung ist nichtig, eine Erstattung ist deshalb nicht nötig","Die Zahlung ist nicht nichtig. Der Rückgewähranspruch folgt aus § 31 GmbHG."]],
   n:"Ausnahme: vollwertiger Gegenleistungs- oder Rückgewähranspruch (bilanzielle Betrachtung, § 30 Abs. 1 S. 2 GmbHG)."},
  {q:"Nach welcher Vorschrift haftet ein GmbH-Geschäftsführer heute für Zahlungen, die er nach Eintritt der Zahlungsunfähigkeit oder Überschuldung leistet?",
   h:"Mit dem SanInsFoG wurden die Zahlungsverbote 2021 rechtsformübergreifend in die InsO verlagert.",
   o:[["§ 15b InsO","Seit 1.1.2021. Zulässig sind nur Zahlungen, die mit der Sorgfalt eines ordentlichen Geschäftsleiters vereinbar sind (§ 15b Abs. 1 S. 2 InsO)."],
      ["§ 64 GmbHG","Die Vorschrift wurde mit Wirkung zum 1.1.2021 aufgehoben."],
      ["§ 30 GmbHG","Das ist das Auszahlungsverbot zur Kapitalerhaltung."],
      ["§ 15a InsO","§ 15a InsO regelt die Antragspflicht. Ihre Verletzung ist strafbar (§ 15a Abs. 4 InsO)."]],
   n:"Zahlungen während der Antragsfrist sind privilegiert, solange Maßnahmen zur Beseitigung der Insolvenzreife betrieben werden (§ 15b Abs. 2 InsO)."},
  {q:"Ein Gesellschafter mit 50 % Beteiligung erhält sein Darlehen von der GmbH 8 Monate vor dem Insolvenzantrag zurück. Was gilt?",
   h:"Prüfe § 135 Abs. 1 Nr. 2 InsO und das Kleinbeteiligungsprivileg (§ 39 Abs. 5 InsO).",
   o:[["Die Rückzahlung ist anfechtbar, weil sie im letzten Jahr vor dem Antrag erfolgt ist (§ 135 Abs. 1 Nr. 2 InsO)","Der Gesellschafter muss den Betrag zur Masse zurückgewähren (§ 143 InsO). Seine Forderung ist nachrangig (§ 39 Abs. 1 Nr. 5 InsO)."],
      ["Unanfechtbar, weil das Darlehen fällig war","Auf die Fälligkeit kommt es bei § 135 InsO nicht an."],
      ["Anfechtbar nur bei Rückzahlung im letzten Monat","Die Frist für Befriedigungen beträgt ein Jahr. Für Sicherungen sind es 10 Jahre (§ 135 Abs. 1 Nr. 1 InsO)."],
      ["Unanfechtbar, weil Gesellschafter wie normale Gläubiger behandelt werden","Gesellschafterdarlehen sind im Insolvenzrecht nachrangig und anfechtungsgefährdet."]],
   n:"Ausnahmen: nicht geschäftsführende Gesellschafter mit höchstens 10 % (§ 39 Abs. 5 InsO) und das Sanierungsprivileg (§ 39 Abs. 4 S. 2 InsO)."},
  {q:"Wann kann ein Fremdgeschäftsführer einer GmbH abberufen werden?",
   h:"§ 38 GmbHG. Wer ist zuständig (§ 46 GmbHG)? Unterscheide die Organstellung vom Anstellungsvertrag.",
   o:[["Jederzeit durch Beschluss der Gesellschafterversammlung (§ 38 Abs. 1, § 46 Nr. 5 GmbHG)","Die Satzung kann die Abberufung auf wichtige Gründe beschränken (§ 38 Abs. 2 GmbHG). Der Anstellungsvertrag muss gesondert gekündigt werden."],
      ["Nur aus wichtigem Grund","Das gilt nur bei entsprechender Satzungsregelung oder beim Vorstand einer AG (§ 84 Abs. 4 AktG)."],
      ["Nur durch das Registergericht","Das Registergericht trägt die Abberufung nur ein (§ 39 GmbHG)."],
      ["Nur mit Zustimmung des Betriebsrats","Die Abberufung ist eine reine Organentscheidung."]],
   n:"In einer nach dem MitbestG mitbestimmten GmbH ist der Aufsichtsrat zuständig (§ 31 MitbestG i. V. m. § 84 AktG)."},
  {q:"Welche Mehrheit und Form braucht eine Satzungsänderung bei der GmbH?",
   h:"§ 53 GmbHG. Wann wird die Änderung wirksam (§ 54 GmbHG)?",
   o:[["Drei Viertel der abgegebenen Stimmen, notariell beurkundet; wirksam mit Eintragung","§ 53 Abs. 2 und § 54 Abs. 3 GmbHG. Eine Vermehrung der Gesellschafterpflichten braucht zusätzlich die Zustimmung aller Betroffenen (§ 53 Abs. 3 GmbHG)."],
      ["Einfache Mehrheit, schriftlich","Die einfache Mehrheit gilt für gewöhnliche Beschlüsse (§ 47 Abs. 1 GmbHG)."],
      ["Einstimmigkeit","Einstimmigkeit ist nicht vorgeschrieben."],
      ["Drei Viertel des gesamten Stammkapitals","Maßgeblich sind die abgegebenen Stimmen. Bei der AG kommt es auf das vertretene Grundkapital an (§ 179 Abs. 2 AktG)."]],
   n:"Bei der AG ist zusätzlich die einfache Stimmenmehrheit erforderlich (§ 133 AktG)."}
 ]},
 { title:"Aktienrecht", icon:"🏛️", qs:[
  {q:"Kann der Aufsichtsrat dem Vorstand einer AG verbindliche Weisungen zur Geschäftsführung erteilen?",
   h:"§ 76 Abs. 1 AktG und § 111 Abs. 4 AktG. Welches Instrument steht dem Aufsichtsrat zur Verfügung?",
   o:[["Nein; er kann aber bestimmte Geschäfte an seine Zustimmung binden (§ 111 Abs. 4 S. 2 AktG)","Der Vorstand leitet die Gesellschaft in eigener Verantwortung (§ 76 Abs. 1 AktG). Geschäftsführungsmaßnahmen können dem AR nicht übertragen werden."],
      ["Ja, wie die Gesellschafter einer GmbH","Bei der GmbH haben die Gesellschafter ein Weisungsrecht (§ 37 Abs. 1 GmbHG), bei der AG gibt es keines."],
      ["Ja, aber nur mit Zustimmung der Hauptversammlung","Auch die HV entscheidet über Geschäftsführungsfragen nur auf Verlangen des Vorstands (§ 119 Abs. 2 AktG)."],
      ["Nur bei Geschäften über 1 Mio. €","Eine solche Grenze gibt es nicht."]],
   n:"Ausnahme: Weisungsrecht des herrschenden Unternehmens bei einem Beherrschungsvertrag (§ 308 AktG)."},
  {q:"Wer bestellt den Vorstand einer AG und für welche Höchstdauer?",
   h:"§ 84 AktG. Unterscheide die Zuständigkeiten von Aufsichtsrat und Hauptversammlung.",
   o:[["Der Aufsichtsrat, für höchstens 5 Jahre (§ 84 Abs. 1 AktG)","Eine wiederholte Bestellung ist zulässig, frühestens ein Jahr vor Ablauf der Amtszeit."],
      ["Die Hauptversammlung, für höchstens 4 Jahre","Die HV wählt den Aufsichtsrat (§ 101 AktG), nicht den Vorstand."],
      ["Der Aufsichtsrat, unbefristet","Die Bestellung ist zwingend auf höchstens 5 Jahre befristet."],
      ["Der Abschlussprüfer","Der Abschlussprüfer hat keine Organkompetenzen."]],
   n:"Abberufung nur aus wichtigem Grund (§ 84 Abs. 4 AktG), z. B. grobe Pflichtverletzung oder Vertrauensentzug durch die HV."},
  {q:"Der Vorstand trifft nach sorgfältiger Prüfung eine Investitionsentscheidung, die sich später als Fehlschlag erweist. Haftet er nach § 93 AktG?",
   h:"Prüfe die Business Judgment Rule in § 93 Abs. 1 S. 2 AktG. Welche Voraussetzungen hat sie?",
   o:[["Nein, wenn er vernünftigerweise annehmen durfte, auf Grundlage angemessener Information zum Wohle der Gesellschaft zu handeln","Business Judgment Rule: Dann liegt keine Pflichtverletzung vor. Für Gesetzesverstöße gilt sie nicht (Legalitätspflicht)."],
      ["Ja, der Vorstand haftet für jeden wirtschaftlichen Misserfolg","Eine Erfolgshaftung gibt es nicht."],
      ["Nein, Vorstände haften nie gegenüber der Gesellschaft","Bei Pflichtverletzungen haften sie als Gesamtschuldner (§ 93 Abs. 2 AktG)."],
      ["Ja, wenn die Hauptversammlung die Entscheidung nicht vorher genehmigt hat","Eine Vorabgenehmigung durch die HV ist nicht vorgesehen."]],
   n:"Beweislast: Der Vorstand muss beweisen, dass er pflichtgemäß gehandelt hat (§ 93 Abs. 2 S. 2 AktG)."},
  {q:"Wer stellt den Jahresabschluss einer AG im Regelfall fest?",
   h:"§§ 172, 173 AktG: Wer billigt den Abschluss, und wann ist ausnahmsweise die HV zuständig?",
   o:[["Vorstand und Aufsichtsrat: Billigt der AR den vom Vorstand aufgestellten Abschluss, ist er festgestellt (§ 172 AktG)","Die HV stellt nur fest, wenn Vorstand und AR das beschließen oder der AR nicht billigt (§ 173 AktG)."],
      ["Die Hauptversammlung","Die HV beschließt im Regelfall nur über die Verwendung des Bilanzgewinns (§ 174 AktG)."],
      ["Der Abschlussprüfer","Der Prüfer erteilt den Bestätigungsvermerk, er stellt nicht fest."],
      ["Der Vorstand allein","Er stellt den Abschluss nur auf (§ 264 HGB)."]],
   n:"Bei der GmbH stellen die Gesellschafter fest (§ 46 Nr. 1 GmbHG)."},
  {q:"Vorstand und Aufsichtsrat stellen den Jahresabschluss fest. Welchen Teil des Jahresüberschusses dürfen sie ohne Satzungsregelung in andere Gewinnrücklagen einstellen?",
   h:"§ 58 Abs. 2 AktG begrenzt die Rücklagenbildung durch die Verwaltung, um das Dividendenrecht der Aktionäre zu schützen.",
   o:[["Höchstens die Hälfte (§ 58 Abs. 2 S. 1 AktG)","Vorher sind Einstellungen in die gesetzliche Rücklage und ein Verlustvortrag abzuziehen. Die Satzung kann einen anderen Anteil vorsehen, bei börsennotierten AG nur einen größeren."],
      ["Den gesamten Jahresüberschuss","Dann bliebe den Aktionären kein Bilanzgewinn."],
      ["Höchstens ein Viertel","Ein Viertel ist keine Grenze des § 58 AktG."],
      ["Nichts, darüber entscheidet nur die HV","Die Verwaltung hat eine eigene Kompetenz nach § 58 Abs. 2 AktG."]],
   n:"Die HV kann im Gewinnverwendungsbeschluss weitere Beträge in Rücklagen einstellen (§ 58 Abs. 3 AktG)."},
  {q:"Welchen Betrag muss eine AG jährlich in die gesetzliche Rücklage einstellen?",
   h:"§ 150 Abs. 2 AktG: Prozentsatz und Obergrenze.",
   o:[["5 % des um einen Verlustvortrag geminderten Jahresüberschusses, bis gesetzliche Rücklage und Kapitalrücklagen nach § 272 Abs. 2 Nr. 1–3 HGB 10 % des Grundkapitals erreichen","Die Satzung kann einen höheren Anteil des Grundkapitals bestimmen."],
      ["25 % des Jahresüberschusses","25 % gilt für die UG (haftungsbeschränkt) nach § 5a Abs. 3 GmbHG."],
      ["10 % des Jahresüberschusses ohne Obergrenze","Prozentsatz und fehlende Obergrenze sind falsch."],
      ["Keine Pflicht","Die gesetzliche Rücklage ist für die AG zwingend."]],
   n:"Verwendung u. a. zum Ausgleich eines Jahresfehlbetrags oder Verlustvortrags (§ 150 Abs. 3 und 4 AktG)."},
  {q:"Was gilt für das genehmigte Kapital (§ 202 AktG)?",
   h:"Wer ermächtigt wen, wie lange und in welcher Höhe?",
   o:[["Satzung bzw. HV ermächtigen den Vorstand für höchstens 5 Jahre, das Grundkapital um bis zu 50 % zu erhöhen","§ 202 Abs. 1–3 AktG. Die neuen Aktien sollen nur mit Zustimmung des AR ausgegeben werden."],
      ["Der Aufsichtsrat ermächtigt den Vorstand unbefristet","Ermächtigen kann nur die Satzung bzw. die HV durch Satzungsänderung."],
      ["Erhöhung um bis zu 100 % für 10 Jahre","Grenzen sind 50 % des Grundkapitals und 5 Jahre."],
      ["Es dient vor allem der Bedienung von Wandelanleihen","Dafür ist das bedingte Kapital da (§ 192 AktG)."]],
   n:"Vereinfachter Bezugsrechtsausschluss bei Barerhöhung bis 20 % des Grundkapitals und Ausgabe nahe am Börsenkurs (§ 186 Abs. 3 S. 4 AktG)."}
 ]},
 { title:"Konzern- & Umwandlungsrecht", icon:"🔗", qs:[
  {q:"Die M-AG hält 60 % der Stimmrechte an der T-AG. Was wird gesetzlich vermutet?",
   h:"Lies § 16, § 17 Abs. 2 und § 18 Abs. 1 S. 3 AktG als Vermutungskette.",
   o:[["Abhängigkeit der T-AG (§ 17 Abs. 2 AktG) und darauf aufbauend ein Konzern (§ 18 Abs. 1 S. 3 AktG)","Beide Vermutungen sind widerleglich, z. B. durch einen Entherrschungsvertrag."],
      ["Ein Beherrschungsvertrag","Ein Unternehmensvertrag muss abgeschlossen und eingetragen werden (§§ 293, 294 AktG)."],
      ["Eine Eingliederung","Die Eingliederung setzt einen HV-Beschluss voraus (§§ 319 ff. AktG), bei der Mehrheitseingliederung mindestens 95 %."],
      ["Nichts, Vermutungen gibt es erst ab 75 %","Die Abhängigkeitsvermutung knüpft schon an die Mehrheitsbeteiligung an."]],
   n:"Unterscheide Vertragskonzern (Beherrschungsvertrag) und faktischen Konzern (§§ 311 ff. AktG)."},
  {q:"Zwischen der M-GmbH und der T-AG besteht ein Gewinnabführungsvertrag. Die T-AG erleidet einen Jahresfehlbetrag. Was gilt?",
   h:"§ 302 AktG regelt die Pflicht des anderen Vertragsteils.",
   o:[["Die M-GmbH muss den Jahresfehlbetrag ausgleichen (Verlustübernahme, § 302 Abs. 1 AktG)","Außenstehende Aktionäre haben Anspruch auf Ausgleich (§ 304 AktG) und Abfindung (§ 305 AktG)."],
      ["Die T-AG trägt ihren Verlust selbst","Gerade das schließt § 302 AktG aus."],
      ["Die M-GmbH muss nur die Hälfte ausgleichen","Auszugleichen ist der gesamte Jahresfehlbetrag, soweit er nicht aus während des Vertrags gebildeten anderen Gewinnrücklagen gedeckt wird."],
      ["Der Vertrag endet automatisch","Ein Verlust beendet den Vertrag nicht."]],
   n:"Steuerlich ist der Gewinnabführungsvertrag Voraussetzung der Organschaft (§ 14 KStG, mindestens 5 Jahre)."},
  {q:"Faktischer AG-Konzern ohne Beherrschungsvertrag: Das herrschende Unternehmen veranlasst die abhängige AG zu einem nachteiligen Geschäft. Was gilt?",
   h:"§ 311 AktG lässt eine Einflussnahme zu, aber nur unter einer Bedingung.",
   o:[["Zulässig nur, wenn der Nachteil bis zum Ende des Geschäftsjahres ausgeglichen oder ein Rechtsanspruch darauf gewährt wird (§ 311 AktG)","Sonst haften das herrschende Unternehmen und seine gesetzlichen Vertreter (§ 317 AktG). Der Vorstand der abhängigen AG erstellt einen Abhängigkeitsbericht (§ 312 AktG)."],
      ["Unbeschränkt zulässig","Ohne Beherrschungsvertrag gibt es kein Weisungsrecht nach § 308 AktG."],
      ["Stets nichtig","Das Gesetz lässt die nachteilige Einflussnahme gegen Nachteilsausgleich zu."],
      ["Zulässig, aber nur mit Zustimmung der Hauptversammlung","Eine Zustimmung der HV ist nicht vorgesehen."]],
   n:"Der Abhängigkeitsbericht wird vom Abschlussprüfer geprüft (§ 313 AktG)."},
  {q:"Die X-GmbH überträgt einen Teilbetrieb auf eine neue Tochtergesellschaft und erhält dafür selbst die Anteile. Welche Umwandlungsart liegt vor?",
   h:"§ 123 UmwG unterscheidet Aufspaltung, Abspaltung und Ausgliederung. Wer erhält jeweils die Anteile?",
   o:[["Ausgliederung (§ 123 Abs. 3 UmwG)","Die Anteile gehen an den übertragenden Rechtsträger selbst. Dieser besteht fort."],
      ["Abspaltung (§ 123 Abs. 2 UmwG)","Bei der Abspaltung erhalten die Anteilsinhaber des übertragenden Rechtsträgers die neuen Anteile."],
      ["Aufspaltung (§ 123 Abs. 1 UmwG)","Bei der Aufspaltung erlischt der übertragende Rechtsträger."],
      ["Formwechsel (§ 190 UmwG)","Beim Formwechsel ändert sich nur die Rechtsform, es wird kein Vermögen übertragen."]],
   n:"Bei Spaltungen haften die beteiligten Rechtsträger als Gesamtschuldner für die Altverbindlichkeiten (§ 133 UmwG)."},
  {q:"Wie alt darf die Schlussbilanz des übertragenden Rechtsträgers bei Anmeldung einer Verschmelzung höchstens sein?",
   h:"§ 17 Abs. 2 UmwG enthält die Frist. Sie ist auch steuerlich relevant (§ 2 UmwStG).",
   o:[["Ihr Stichtag darf höchstens 8 Monate vor der Anmeldung liegen","§ 17 Abs. 2 S. 4 UmwG. Die steuerliche Rückwirkung knüpft daran an."],
      ["12 Monate","Diese Frist ist zu lang."],
      ["6 Monate","Diese Frist ist zu kurz."],
      ["Es gibt keine Frist","Das Registergericht darf die Verschmelzung bei älterer Bilanz nicht eintragen."]],
   n:"Für die Schlussbilanz gelten die Vorschriften über die Jahresbilanz und ihre Prüfung entsprechend (§ 17 Abs. 2 S. 2 UmwG)."},
  {q:"Ab welcher Beteiligung kann ein Hauptaktionär die Minderheitsaktionäre einer AG nach § 327a AktG gegen Barabfindung ausschließen?",
   h:"Unterscheide den aktienrechtlichen, den verschmelzungsrechtlichen und den übernahmerechtlichen Squeeze-out.",
   o:[["95 % des Grundkapitals","Aktienrechtlicher Squeeze-out (§ 327a Abs. 1 AktG), HV-Beschluss erforderlich."],
      ["90 %","Das ist die Schwelle des verschmelzungsrechtlichen Squeeze-out (§ 62 Abs. 5 UmwG), bei dem der Hauptaktionär eine AG, KGaA oder SE sein muss."],
      ["75 %","75 % ist die typische Mehrheit für Grundlagenbeschlüsse wie Satzungsänderungen."],
      ["Mehr als 50 %","Eine einfache Mehrheit reicht für einen Ausschluss nicht."]],
   n:"Die Angemessenheit der Barabfindung kann im Spruchverfahren überprüft werden (SpruchG)."}
 ]},
 { title:"Insolvenz & Sanierung", icon:"🆘", qs:[
  {q:"Innerhalb welcher Frist muss der Geschäftsführer einer GmbH spätestens Insolvenzantrag stellen?",
   h:"§ 15a Abs. 1 InsO unterscheidet zwischen den Insolvenzgründen. Seit dem SanInsFoG gibt es unterschiedliche Höchstfristen.",
   o:[["Bei Zahlungsunfähigkeit spätestens nach 3 Wochen, bei Überschuldung spätestens nach 6 Wochen, jeweils ohne schuldhaftes Zögern","§ 15a Abs. 1 S. 2 InsO. Die Fristen sind Höchstfristen, keine Schonfristen."],
      ["Einheitlich 3 Wochen","Für die Überschuldung gelten seit 2021 6 Wochen."],
      ["Innerhalb von 3 Monaten","3 Monate sind der Zeitraum der besonderen Insolvenzanfechtung (§§ 130, 131 InsO)."],
      ["Schon bei drohender Zahlungsunfähigkeit","Bei drohender Zahlungsunfähigkeit besteht nur ein Antragsrecht (§ 18 InsO)."]],
   n:"Bei Führungslosigkeit sind auch die Gesellschafter antragspflichtig (§ 15a Abs. 3 InsO)."},
  {q:"Wann liegt nach der Rechtsprechung des BGH regelmäßig Zahlungsunfähigkeit vor (§ 17 InsO)?",
   h:"Unterscheide eine vorübergehende Zahlungsstockung von der Zahlungsunfähigkeit. Welche Schwelle und welcher Zeitraum gelten?",
   o:[["Bei einer Liquiditätslücke von 10 % oder mehr, die nicht innerhalb von drei Wochen geschlossen werden kann","Ausnahme: Die Lücke wird mit an Sicherheit grenzender Wahrscheinlichkeit demnächst geschlossen. Unter 10 % ist grundsätzlich von einer Zahlungsstockung auszugehen."],
      ["Bei jeder noch so kleinen Liquiditätslücke","Geringfügige Lücken unter 10 % sind grundsätzlich unschädlich."],
      ["Wenn das Eigenkapital negativ ist","Das betrifft die Überschuldung (§ 19 InsO), und auch dort nur ohne positive Fortführungsprognose."],
      ["Erst wenn alle Gläubiger mahnen","Eine Mahnung ist keine Voraussetzung. Maßgeblich sind die fälligen Verbindlichkeiten."]],
   n:"Die Zahlungseinstellung begründet die Vermutung der Zahlungsunfähigkeit (§ 17 Abs. 2 S. 2 InsO)."},
  {q:"Welche Prognosezeiträume gelten für die Überschuldung (§ 19 InsO) und die drohende Zahlungsunfähigkeit (§ 18 InsO)?",
   h:"Beide Zeiträume wurden mit dem SanInsFoG ausdrücklich ins Gesetz geschrieben.",
   o:[["Überschuldung: 12 Monate; drohende Zahlungsunfähigkeit: in aller Regel 24 Monate","§ 19 Abs. 2 S. 1 und § 18 Abs. 2 S. 2 InsO."],
      ["Beide 12 Monate","Für die drohende Zahlungsunfähigkeit ist der Zeitraum länger."],
      ["Überschuldung: 24 Monate; drohende Zahlungsunfähigkeit: 12 Monate","Die Zeiträume sind vertauscht."],
      ["Beide bis zum Ende des folgenden Geschäftsjahres","Das war eine frühere Praxisformel ohne ausdrückliche gesetzliche Grundlage."]],
   n:"Überschuldung zweistufig: Ist die Fortführungsprognose positiv, liegt keine Überschuldung vor. Ist sie negativ, folgt ein Überschuldungsstatus zu Liquidationswerten."},
  {q:"Für welchen Zeitraum vor dem Insolvenzantrag kann der Verwalter Rechtshandlungen wegen Vorsatzanfechtung (§ 133 Abs. 1 InsO) anfechten, die dem Gläubiger keine Sicherung oder Befriedigung gewähren?",
   h:"Seit der Reform von 2017 unterscheidet § 133 InsO zwischen Deckungshandlungen und sonstigen Handlungen.",
   o:[["10 Jahre","§ 133 Abs. 1 InsO. Voraussetzungen: Benachteiligungsvorsatz des Schuldners und Kenntnis des Anfechtungsgegners."],
      ["4 Jahre","4 Jahre gelten für Deckungshandlungen, also Sicherung oder Befriedigung (§ 133 Abs. 2 InsO)."],
      ["3 Monate","Das ist der Zeitraum der besonderen Insolvenzanfechtung (§§ 130, 131 InsO)."],
      ["1 Jahr","Das ist z. B. die Frist für die Rückgewähr von Gesellschafterdarlehen (§ 135 Abs. 1 Nr. 2 InsO)."]],
   n:"Bei Deckungshandlungen wird die Kenntnis erst bei eingetretener, nicht schon bei drohender Zahlungsunfähigkeit vermutet (§ 133 Abs. 3 InsO)."},
  {q:"Ein Lieferant hat Ware unter einfachem Eigentumsvorbehalt an eine GmbH geliefert, die jetzt insolvent ist. Welches Recht hat er?",
   h:"Unterscheide Aussonderung (§ 47 InsO: Gegenstand gehört nicht zur Masse) und Absonderung (§§ 49 ff. InsO: bevorzugte Befriedigung aus dem Gegenstand).",
   o:[["Ein Aussonderungsrecht: Er kann die Ware herausverlangen (§ 47 InsO)","Er ist noch Eigentümer. Wählt der Verwalter Erfüllung (§ 103 InsO), muss er den Restkaufpreis zahlen. Die Entscheidung kann bis nach dem Berichtstermin aufgeschoben werden (§ 107 Abs. 2 InsO)."],
      ["Ein Absonderungsrecht","Das gilt beim verlängerten oder erweiterten Eigentumsvorbehalt und bei der Sicherungsübereignung (§ 51 Nr. 1 InsO)."],
      ["Er ist einfacher Insolvenzgläubiger mit Quote","Er hat ein dingliches Recht an der Ware."],
      ["Er hat automatisch eine Masseforderung","Masseverbindlichkeiten entstehen erst durch Handlungen des Verwalters oder bei Erfüllungswahl."]],
   n:"Rangfolge: Aus- und Absonderung → Masseverbindlichkeiten (§§ 53 ff. InsO) → Insolvenzgläubiger (§ 38 InsO) → nachrangige Gläubiger (§ 39 InsO)."},
  {q:"Unter welcher Voraussetzung kann ein Unternehmen den Stabilisierungs- und Restrukturierungsrahmen nach dem StaRUG nutzen?",
   h:"Das StaRUG soll eine Sanierung vor der Insolvenz ermöglichen. Welcher Insolvenzgrund ist die Zugangsvoraussetzung?",
   o:[["Bei drohender Zahlungsunfähigkeit (§ 29 Abs. 1 StaRUG)","Tritt Zahlungsunfähigkeit oder Überschuldung ein, muss der Schuldner das anzeigen (§ 42 StaRUG). Die Restrukturierungssache kann dann aufgehoben werden."],
      ["Nur bei eingetretener Zahlungsunfähigkeit","Dann ist grundsätzlich das Insolvenzverfahren vorrangig."],
      ["Nur mit Zustimmung aller Gläubiger","Der Restrukturierungsplan kann mit 75 % in jeder Gruppe angenommen werden (§ 25 StaRUG). Ablehnende Gruppen können überstimmt werden (§ 26 StaRUG)."],
      ["Nur bei börsennotierten Unternehmen","Der Rahmen steht grundsätzlich allen unternehmerisch tätigen Schuldnern offen."]],
   n:"Arbeitnehmerforderungen und Ansprüche aus betrieblicher Altersversorgung können nicht gestaltet werden (§ 4 StaRUG)."}
 ]},
 { title:"Arbeitsrecht", icon:"👷", qs:[
  {q:"Ein Betrieb hat 15 Vollzeitbeschäftigte. Eine Arbeitnehmerin ist seit 8 Monaten beschäftigt. Hat sie Kündigungsschutz nach dem KSchG?",
   h:"Prüfe den betrieblichen (§ 23 KSchG) und den persönlichen Anwendungsbereich (§ 1 Abs. 1 KSchG).",
   o:[["Ja: mehr als 10 Arbeitnehmer und mehr als 6 Monate Betriebszugehörigkeit","Die Kündigung muss dann sozial gerechtfertigt sein, also personen-, verhaltens- oder betriebsbedingt (§ 1 Abs. 2 KSchG)."],
      ["Nein, die Wartezeit beträgt 12 Monate","Die Wartezeit beträgt 6 Monate."],
      ["Nein, das KSchG gilt erst ab 20 Arbeitnehmern","Die Schwelle liegt bei mehr als 10 Arbeitnehmern."],
      ["Ja, und zwar unabhängig von der Betriebsgröße","Im Kleinbetrieb mit bis zu 10 Arbeitnehmern gilt das KSchG nicht (§ 23 Abs. 1 KSchG)."]],
   n:"Teilzeitkräfte zählen anteilig: bis 20 Wochenstunden 0,5, bis 30 Stunden 0,75 (§ 23 Abs. 1 S. 4 KSchG)."},
  {q:"Ein Arbeitnehmer erhält die schriftliche Kündigung und hält sie für sozialwidrig. Was muss er beachten?",
   h:"§ 4 KSchG enthält eine Klagefrist. Was passiert, wenn sie versäumt wird (§ 7 KSchG)?",
   o:[["Er muss innerhalb von drei Wochen nach Zugang Kündigungsschutzklage beim Arbeitsgericht erheben","Sonst gilt die Kündigung als von Anfang an wirksam (§ 7 KSchG). Ausnahme: nachträgliche Zulassung der Klage (§ 5 KSchG)."],
      ["Er hat einen Monat Zeit für einen Widerspruch beim Arbeitgeber","Ein Widerspruch beim Arbeitgeber ersetzt die Klage nicht."],
      ["Er kann innerhalb der Regelverjährung von 3 Jahren klagen","Die Klagefrist ist eine Sonderregel und viel kürzer."],
      ["Er muss zuerst den Betriebsrat anrufen","Ein Einspruch beim Betriebsrat (§ 3 KSchG) ist möglich, verlängert die Klagefrist aber nicht."]],
   n:"Die Dreiwochenfrist gilt für alle Unwirksamkeitsgründe, nicht nur für die Sozialwidrigkeit."},
  {q:"Ein Arbeitgeber kündigt per E-Mail mit eingescannter Unterschrift. Ist die Kündigung wirksam?",
   h:"§ 623 BGB schreibt eine Form vor. Ist die elektronische Form zugelassen?",
   o:[["Nein, es gilt die Schriftform mit eigenhändiger Unterschrift; die elektronische Form ist ausgeschlossen (§ 623 BGB)","Die Kündigung ist nichtig (§ 125 BGB). Dasselbe gilt für Aufhebungsverträge."],
      ["Ja, seit 2025 reicht die Textform","Erleichterungen gab es beim Nachweisgesetz, nicht bei § 623 BGB."],
      ["Ja, wenn der Arbeitnehmer die E-Mail gelesen hat","Die Kenntnisnahme heilt den Formmangel nicht."],
      ["Ja, mit qualifizierter elektronischer Signatur","§ 623 BGB schließt die elektronische Form ausdrücklich aus."]],
   n:"Die Klagefrist des § 4 KSchG beginnt erst mit Zugang einer schriftlichen Kündigung."},
  {q:"Ein Arbeitnehmer ist seit 10 Jahren im Betrieb. Mit welcher gesetzlichen Frist kann der Arbeitgeber ordentlich kündigen?",
   h:"§ 622 Abs. 2 BGB staffelt die Fristen für Kündigungen durch den Arbeitgeber nach der Betriebszugehörigkeit.",
   o:[["4 Monate zum Ende eines Kalendermonats","§ 622 Abs. 2 S. 1 Nr. 4 BGB."],
      ["4 Wochen zum 15. oder zum Monatsende","Das ist die Grundkündigungsfrist (§ 622 Abs. 1 BGB). Der Arbeitnehmer selbst kann mit dieser Frist kündigen."],
      ["3 Monate zum Monatsende","Das gilt ab 8 Jahren Betriebszugehörigkeit."],
      ["6 Monate zum Monatsende","Das gilt ab 15 Jahren."]],
   n:"Die Regel, Beschäftigungszeiten vor dem 25. Lebensjahr nicht mitzurechnen, ist europarechtswidrig und wird nicht angewendet."},
  {q:"Der Arbeitgeber erfährt am 1.6. von einer Unterschlagung durch einen Mitarbeiter. Bis wann muss er fristlos kündigen?",
   h:"§ 626 Abs. 2 BGB enthält eine Ausschlussfrist. Ab wann läuft sie?",
   o:[["Innerhalb von zwei Wochen ab Kenntnis der maßgeblichen Tatsachen","§ 626 Abs. 2 BGB. Eine zügige Anhörung des Arbeitnehmers kann den Fristbeginn hinausschieben."],
      ["Innerhalb von drei Wochen","Drei Wochen sind die Klagefrist des Arbeitnehmers (§ 4 KSchG)."],
      ["Innerhalb eines Monats","Diese Frist gibt es bei § 626 BGB nicht."],
      ["Jederzeit, solange der Arbeitnehmer noch beschäftigt ist","Nach Ablauf der zwei Wochen ist die fristlose Kündigung ausgeschlossen."]],
   n:"Ein wichtiger Grund liegt vor, wenn die Fortsetzung bis zum Ablauf der Kündigungsfrist unzumutbar ist (Interessenabwägung)."},
  {q:"Ein Arbeitgeber kündigt, ohne den bestehenden Betriebsrat vorher anzuhören. Folge?",
   h:"Schau in § 102 Abs. 1 BetrVG.",
   o:[["Die Kündigung ist unwirksam (§ 102 Abs. 1 S. 3 BetrVG)","Der Betriebsrat ist vor jeder Kündigung anzuhören. Zustimmen muss er nicht; sein Widerspruch macht die Kündigung grundsätzlich nicht unwirksam."],
      ["Die Kündigung ist wirksam, der Arbeitgeber zahlt ein Bußgeld","Die fehlende Anhörung führt zur Unwirksamkeit."],
      ["Die Kündigung ist wirksam, wenn sie sozial gerechtfertigt ist","Die Anhörung ist eine eigenständige Wirksamkeitsvoraussetzung."],
      ["Der Betriebsrat muss nur bei fristlosen Kündigungen angehört werden","Die Anhörung ist bei ordentlichen und außerordentlichen Kündigungen nötig."]],
   n:"Äußerungsfristen des Betriebsrats: eine Woche bei ordentlicher, drei Tage bei außerordentlicher Kündigung (§ 102 Abs. 2 BetrVG)."},
  {q:"Ein Betrieb wird durch Kaufvertrag auf einen neuen Inhaber übertragen. Was passiert mit den Arbeitsverhältnissen?",
   h:"§ 613a BGB: Rechtsfolge, Kündigungsverbot, Widerspruchsrecht.",
   o:[["Sie gehen kraft Gesetzes auf den Erwerber über; Arbeitnehmer können innerhalb eines Monats nach Unterrichtung widersprechen","§ 613a Abs. 1 und 6 BGB. Eine Kündigung wegen des Betriebsübergangs ist unwirksam (§ 613a Abs. 4 BGB)."],
      ["Sie enden automatisch mit dem Übergang","Gerade das verhindert § 613a BGB."],
      ["Sie gehen nur mit Zustimmung jedes Arbeitnehmers über","Eine Zustimmung ist nicht erforderlich, es gibt nur ein Widerspruchsrecht."],
      ["Der Erwerber kann frei auswählen, wen er übernimmt","Alle dem übertragenen Betrieb zugeordneten Arbeitsverhältnisse gehen über."]],
   n:"Bei fehlerhafter Unterrichtung beginnt die Widerspruchsfrist nicht zu laufen."}
 ]},
 { title:"Europa- & Kapitalmarktrecht", icon:"🇪🇺", qs:[
  {q:"Was unterscheidet eine EU-Verordnung von einer EU-Richtlinie?",
   h:"Art. 288 AEUV: Für wen ist der Rechtsakt verbindlich, und braucht er eine Umsetzung?",
   o:[["Die Verordnung gilt unmittelbar in jedem Mitgliedstaat; die Richtlinie ist nur hinsichtlich ihres Ziels verbindlich und muss umgesetzt werden","Beispiel: EU-Abschlussprüferverordnung (Verordnung) vs. Abschlussprüferrichtlinie (in HGB und WPO umgesetzt)."],
      ["Die Richtlinie gilt unmittelbar, die Verordnung muss umgesetzt werden","Genau umgekehrt."],
      ["Beide sind unverbindliche Empfehlungen","Unverbindlich sind Empfehlungen und Stellungnahmen (Art. 288 Abs. 5 AEUV)."],
      ["Verordnungen gelten nur für einzelne Adressaten","Das trifft auf Beschlüsse zu (Art. 288 Abs. 4 AEUV)."]],
   n:"Nicht fristgerecht umgesetzte Richtlinien können ausnahmsweise unmittelbar gegenüber dem Staat wirken (vertikale Direktwirkung)."},
  {q:"Welche der folgenden ist KEINE Grundfreiheit des AEUV?",
   h:"Zähle die klassischen Binnenmarktfreiheiten auf: Waren, Personen, Dienstleistungen, Kapital.",
   o:[["Freiheit des Steuerwettbewerbs","Die direkten Steuern sind nicht harmonisiert. Die Mitgliedstaaten müssen bei der Besteuerung aber die Grundfreiheiten beachten."],
      ["Niederlassungsfreiheit (Art. 49 AEUV)","Sie ist eine Grundfreiheit und gilt auch für Gesellschaften (Art. 54 AEUV)."],
      ["Kapitalverkehrsfreiheit (Art. 63 AEUV)","Sie ist eine Grundfreiheit und gilt als einzige auch gegenüber Drittstaaten."],
      ["Dienstleistungsfreiheit (Art. 56 AEUV)","Sie ist eine Grundfreiheit, z. B. relevant für grenzüberschreitende Beratung."]],
   n:"Eingriffe in Grundfreiheiten können aus zwingenden Gründen des Allgemeininteresses gerechtfertigt sein, wenn sie verhältnismäßig sind."},
  {q:"Ein letztinstanzliches deutsches Gericht hat Zweifel an der Auslegung einer EU-Richtlinie, auf die es im Verfahren ankommt. Was muss es tun?",
   h:"Art. 267 AEUV unterscheidet zwischen Vorlagerecht und Vorlagepflicht.",
   o:[["Es muss die Frage dem EuGH zur Vorabentscheidung vorlegen (Art. 267 Abs. 3 AEUV)","Ausnahmen: Die Frage ist bereits geklärt (acte éclairé) oder die Auslegung ist offenkundig (acte clair)."],
      ["Es darf die Frage selbst abschließend entscheiden","Das dürfen nur nicht letztinstanzliche Gerichte, die ein Vorlagerecht, aber keine Vorlagepflicht haben."],
      ["Es muss das Bundesverfassungsgericht anrufen","Für die Auslegung des Unionsrechts ist der EuGH zuständig."],
      ["Es muss die EU-Kommission um eine Stellungnahme bitten","Die Kommission entscheidet keine Auslegungsfragen."]],
   n:"Eine willkürliche Nichtvorlage kann das Recht auf den gesetzlichen Richter verletzen (Art. 101 Abs. 1 S. 2 GG)."},
  {q:"Eine nach niederländischem Recht gegründete B.V. verlegt ihren tatsächlichen Verwaltungssitz nach Deutschland. Wie wird sie hier behandelt?",
   h:"Denk an die EuGH-Rechtsprechung zur Niederlassungsfreiheit (Centros, Überseering, Inspire Art).",
   o:[["Sie wird als B.V. anerkannt und bleibt rechtsfähig; ihre Haftungsbeschränkung gilt fort","Für Gesellschaften aus EU- und EWR-Staaten gilt im Ergebnis die Gründungstheorie (Art. 49, 54 AEUV)."],
      ["Sie muss sich in Deutschland als GmbH neu gründen","Das widerspräche der Niederlassungsfreiheit."],
      ["Sie wird als deutsche Personengesellschaft mit unbeschränkter Haftung behandelt","Diese Folge der Sitztheorie wird nur noch gegenüber bestimmten Drittstaaten-Gesellschaften angewendet."],
      ["Sie verliert ihre Rechtsfähigkeit","Der EuGH hat in Überseering die Anerkennung der Rechtsfähigkeit verlangt."]],
   n:"Grenzüberschreitende Verschmelzungen, Spaltungen und Formwechsel sind seit dem UmRUG (2023) im UmwG geregelt."},
  {q:"Eine börsennotierte AG erfährt von einem kursrelevanten Großauftrag. Was verlangt Art. 17 MAR?",
   h:"Die Marktmissbrauchsverordnung (MAR) ist eine EU-Verordnung und gilt unmittelbar. Wann muss die Insiderinformation veröffentlicht werden?",
   o:[["Unverzügliche Veröffentlichung als Ad-hoc-Mitteilung, sofern kein Aufschub zulässig ist","Ein Aufschub ist möglich, wenn berechtigte Interessen bestehen, keine Irreführung droht und die Vertraulichkeit gewährleistet ist (Art. 17 Abs. 4 MAR)."],
      ["Veröffentlichung im nächsten Jahresabschluss","Das wäre viel zu spät."],
      ["Veröffentlichung nur auf Anfrage der BaFin","Die Pflicht besteht von sich aus."],
      ["Veröffentlichung nach § 15 WpHG","§ 15 WpHG a. F. wurde 2016 durch Art. 17 MAR ersetzt."]],
   n:"Schadensersatz bei unterlassener oder unwahrer Ad-hoc-Mitteilung nach §§ 97, 98 WpHG."}
 ]}
];
